export function LucideIcon({
  name,
  size = 18,
  color = 'currentColor',
  strokeWidth = 2,
  className = '',
  ...props
}: LucideIconProps) {
  const content = iconFragments[name];
  if (!content) return null;

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={`lucide-icon lucide-${name} ${className}`.trim()}
      aria-hidden="true"
      {...props}
    >
      {content}
    </svg>
  );
}

export default LucideIcon;
